const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='home',stack=[],savedCategoryDraft=null,savedCategoryStack=[],draft=null,detailId=8,advanceId=11,categoryQuery='',categoryMode=false,categoryOrigin='expense',filter={type:'all',category:'',status:'all',query:''},advanceFilter='open',advanceSearch='',advanceSubject='',advanceProject='',advancePeriod=false,selectedDay='',calendarMonth='2026-11',viewCalendar=false,periodSpan=1,analysisMonth='2026-10',theme='light',textLarge=false,rateChoice=1,modalAction=null,returnFocus=null,toastTimer,simValue='',error='',previousBackup=null;
const device=$('#device'),screen=$('#screen'),overlay=$('#overlay');
const btn=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
