function header(title,right=''){return `<header class="app-header">${btn(icon('back'),'back','icon-button','aria-label="Torna indietro"')}<h2>${title}</h2>${right||'<span></span>'}</header>`;}
function navigation(){return `<nav class="bottom-nav" aria-label="Navigazione principale">${[['home','home','Home'],['movements','history','Movimenti'],['create','plus','Registra'],['analysis','chart','Analisi'],['commitments','calendar','Impegni']].map(([id,ico,name])=>btn(icon(ico)+(id==='create'?'':`<span>${name}</span>`),id==='create'?'create':'go:'+id,id==='create'?'plus':(page===id?'active':''),`aria-label="${name}" ${page===id?'aria-current="page"':''}`)).join('')}</nav>`;}
function layout(title,body,footer='',nav=false,opts=''){const home=page==='home';screen.innerHTML=(home?`<header class="home-header"><div><h2>Ciao!</h2><p>Ecco la tua situazione attuale</p></div>${btn(icon('settings'),'go:settings','icon-button','aria-label="Impostazioni"')}</header>`:header(title,opts))+`<main class="content ${home?'home-content':page==='analysis'?'analysis-content':''} ${['expense','income','planned','series','advance-form','refund','edit'].includes(page)?'form-content':''}" id="main" tabindex="-1">${body}${error?`<div class="error" role="alert">${esc(error)}</div>`:''}</main>`+(footer?`<footer class="form-footer">${footer}</footer>`:'')+(nav?navigation():'')+`<div class="sample-keyboard" aria-label="Tastiera dimostrativa">${['1','2','3','4','5','6','7','8','9',',','0','⌫'].map(x=>btn(x,'key:'+x)).join('')}</div>`;}
function go(p,replace=false){closeModal();error='';if(!replace)stack.push(page);page=p;render();$('#main')?.focus({preventScroll:true});}
function back(){if(page==='categories'&&categoryMode&&savedCategoryDraft){draft=savedCategoryDraft;savedCategoryDraft=null;categoryMode=false;stack=savedCategoryStack.slice();categoryPicker();return;}if(['expense','income','planned','series','advance-form','refund','edit','reserve','opening','reconcile','category-edit'].includes(page)&&draft&&JSON.stringify({...draft,baseline:undefined})!==draft.baseline){confirmDialog('Uscire senza salvare?','Le modifiche apportate verranno perse.','Esci senza salvare',()=>{draft=null;page=stack.pop()||'home';error='';render();},false,'Continua a modificare');return;}page=stack.pop()||'home';error='';render();}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function openModal(html,sheet=false){returnFocus=document.activeElement;overlay.innerHTML=`<section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="${sheet?'sheet':'dialog'}">${html}</section>`;screen.inert=true;setTimeout(()=>overlay.querySelector('button,input')?.focus(),0);}
