function advanceDetail(){const a=state.advances.find(a=>a.id===advanceId);if(!a){layout('Anticipo',empty('Anticipo non disponibile','Torna all’elenco per continuare.'));return;}const list=state.refunds.filter(r=>r.advance===a.id).sort((x,y)=>y.date.localeCompare(x.date));layout('Dettaglio anticipo',`<div class="hero-panel">${medallion('advance')}<h2>${esc(a.description)}</h2><p>${esc(a.debtor)}</p><strong class="big">${money(remaining(a))}</strong><p>${remaining(a)>0?'Ancora da restituire':'Recuperato interamente'}</p>${advanceLabel(a)}<div class="progress"><span style="width:${recovered(a.id)/a.cents*100}%"></span></div></div><div class="detail-lines">${line('Importo anticipato',money(a.cents))}${line('Già restituito',money(recovered(a.id)))}${line('Anticipato il',dateLabel(a.date))}${line('Restituzione prevista',a.due?dateLabel(a.due):'Non indicata')}${a.project?line('Progetto',esc(a.project)):''}${a.cause?line('Causale',esc(a.cause)):''}${a.notes?line('Note',esc(a.notes)):''}</div><section>${section('Rimborsi ricevuti')}${list.map(r=>row(dateLabel(r.date),esc(r.note||'Restituzione ricevuta')+'<br>'+financialBadge({kind:'refund',status:'actual'}),money(r.cents),'refund','refund-menu:'+r.id,'positive')).join('')||note('Non hai ancora registrato rimborsi.')}</section>${note('Ogni rimborso aumenta la liquidità e riduce il residuo. Non è un guadagno personale.')}${btn('Modifica o correggi anticipo','advance-menu','text-link')}`,remaining(a)>0?primary('Registra rimborso','new:refund'):'');}
function advanceForm(){layout(draft.id?'Modifica anticipo':'Registra anticipo',moneyField(draft.amount)+note('Denaro già pagato per conto di altri, da farti restituire.')+field('Per cosa hai anticipato?','description',draft.description,'text','maxlength="64" placeholder="Es. Pulizie appartamento"')+field('Da chi devi recuperarlo?','debtor',draft.debtor,'text','maxlength="64" placeholder="Nome o soggetto"')+field('Data dell’anticipo','date',draft.date,'date')+field('Restituzione prevista (facoltativa)','due',draft.due,'date')+`<details class="advanced"><summary>Progetto, causale e note</summary>${field('Immobile o progetto','project',draft.project)}${field('Causale','cause',draft.cause)}${field('Note','notes',draft.notes)}</details>`,primary('Salva anticipo','save-advance'));}
function refundForm(){const a=state.advances.find(a=>a.id===draft.advance);layout('Registra rimborso',`<div class="selected-category">${medallion('advance',true)}<div><strong>${esc(a.description)}</strong><p class="small-text muted">${esc(a.debtor)} · residuo ${money(remaining(a))}</p></div></div>`+moneyField(draft.amount)+btn('Compila tutto il residuo','refund-all','text-link')+field('Data del rimborso','date',draft.date,'date')+field('Nota (facoltativa)','note',draft.note)+note('Registra solo il denaro già ricevuto. La liquidità aumenterà della stessa somma, senza creare un’entrata personale.'),primary('Salva rimborso ricevuto','save-refund'));}
function calculation(){const t=totals();layout('Come nasce il tuo margine',`<div class="hero-panel"><p>Puoi spendere oggi</p><strong class="big ${t.spendable<0?'negative':''}">${money(t.spendable)}</strong><p>Proteggendo ciò che hai già previsto</p></div><div class="detail-lines">${line('Liquidità effettiva',money(t.cash))}${line('Pagamenti fino al '+dateLabel(state.horizon),'− '+money(t.commitments))}${line('Riserva protetta','− '+money(state.reserve))}${line('Margine spendibile',money(t.spendable),'total')}</div>${note('Le entrate attese e gli anticipi ancora da recuperare non aumentano questa cifra.')}${row('Modifica riserva e periodo','Le regole che proteggono il tuo margine','','shield','go:rules')}${row('Allinea la liquidità di oggi','Correggi il saldo senza inventare un guadagno','','wallet','money:reconcile')}`);}
function simulator(){layout('Simula una spesa',`<p class="support-copy">Se spendo questa cifra oggi, quanto mi rimane davvero?</p>${moneyField(simValue,'simulation')}<div class="sim-result" id="sim-result"></div><div class="detail-lines">${line('Margine attuale',money(totals().spendable))}${line('Impegni protetti',money(totals().commitments))}${line('Riserva protetta',money(state.reserve))}</div><p class="check-line">${icon('shield')}Questa prova non registra movimenti.</p>${btn('Azzera la simulazione','clear-simulation','text-link')}`);updateSimulation();}
function updateSimulation(){const target=$('#sim-result');if(!target)return;try{const n=simValue?cents(simValue):0,after=totals().spendable-n;target.className='sim-result'+(after<0?' exceeded':'');target.innerHTML=`<small>DOPO QUESTA SPESA</small><strong class="${after<0?'negative':''}">${money(after)}</strong><p>${after<0?'Superi il margine prudente di '+money(-after)+'.':'Impegni e riserva restano coperti.'}</p>`;}catch(e){target.innerHTML=`<div class="error" role="alert">${e.message}</div>`;}}
const chartColors=['#4295ef','#a3b9bd','#aa94e3','#f7ad7a','#efbf77','#82c79a','#f28c9c'];
function analysis(){const [y,m]=analysisMonth.split('-').map(Number),from=addDate(analysisMonth+'-01',-(periodSpan-1),'monthly'),through=analysisMonth===MONTH?TODAY:new Date(y,m,0).toISOString().slice(0,10);const expenses=state.operations.filter(o=>o.status==='actual'&&o.kind==='expense'&&o.date>=from&&o.date<=through);const categoryOrder=[7,1,9,2,12,27];const groups=[...state.categories].sort((a,b)=>(categoryOrder.indexOf(a.id)<0?99:categoryOrder.indexOf(a.id))-(categoryOrder.indexOf(b.id)<0?99:categoryOrder.indexOf(b.id))).map(c=>({c,n:expenses.filter(o=>o.category===c.id).reduce((s,o)=>s+o.cents,0)})).filter(x=>x.n>0);const total=groups.reduce((s,x)=>s+x.n,0);let offset=0;const arcs=groups.map((x,i)=>{const v=x.n/(total||1)*100,svg=`<circle cx="120" cy="120" r="91" fill="none" stroke="${chartColors[i%chartColors.length]}" stroke-width="38" pathLength="100" stroke-dasharray="${v} ${100-v}" stroke-dashoffset="${-offset}" transform="rotate(-90 120 120)"/>`;offset+=v;return svg;}).join('');layout('Analisi',`<div class="tabs">${[[1,'Mese'],[3,'Trimestre'],[12,'Anno']].map(([v,n])=>btn(n,'analysis-span:'+v,periodSpan===v?'active':'')).join('')}</div><div class="period">${btn(icon('back'),'analysis-prev','icon-button','aria-label="Periodo precedente"')}<span>${new Date(y,m-1,1).toLocaleDateString('it-IT',{month:'long',year:'numeric'})}</span>${btn(icon('chevron'),'analysis-next','icon-button','aria-label="Periodo successivo"')}</div>${periodSpan>1?note(dateLabel(from)+' – '+dateLabel(through)+' · periodo mobile'):''}<div class="donut-wrap"><svg viewBox="0 0 240 240" role="img" aria-label="Distribuzione delle spese personali"><circle cx="120" cy="120" r="91" fill="none" stroke="var(--line)" stroke-width="38"/>${arcs}</svg><div class="donut-label"><span>Totale uscite</span><strong>${money(total)}</strong></div></div><div class="legend">${groups.map((x,i)=>`<div class="legend-row"><span class="dot" style="background:${chartColors[i%chartColors.length]}"></span><span>${esc(x.c.name)}</span><span class="pct">${Math.round(x.n/total*100)}%</span><strong>${money(x.n)}</strong></div>`).join('')||note('Le tue categorie appariranno dopo la prima spesa.')}</div><section class="chart-section">${section('Andamento liquidità')}${cashChart(from,through)}<div class="chart-dates"><span>${dateLabel(from)}</span><span>${dateLabel(through)}</span></div></section><p class="analysis-note">Saldo effettivo · anticipi e rimborsi inclusi</p>${btn('Confronti, entrate e previsioni','analysis-more','analysis-more')}`,'',true,btn(icon('filter'),'analysis-categories','icon-button','aria-label="Filtra spese per categoria"'));}
function cashChart(from,through,projection=false){let b=state.opening;const points=[{date:from,b:0}],events=cashEvents();events.filter(e=>e.date<from).forEach(e=>b+=e.value);points[0].b=b;events.filter(e=>e.date>=from&&e.date<=through).forEach(e=>{b+=e.value;points.push({date:e.date,b})});points.push({date:through,b});const low=Math.min(...points.map(p=>p.b)),high=Math.max(...points.map(p=>p.b));const range=high-low||100;const x=d=>10+(Date.parse(d)-Date.parse(from))/Math.max(86400000,Date.parse(through)-Date.parse(from))*300,y=v=>75-(v-low)/range*58;let path='M'+x(points[0].date)+' '+y(points[0].b);points.slice(1).forEach(p=>path+=' H'+x(p.date)+' V'+y(p.b));return `<svg viewBox="0 0 320 90" role="img" aria-label="Saldo a gradini, solo movimenti registrati"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#57aafa" stop-opacity=".35"/><stop offset="1" stop-color="#57aafa" stop-opacity="0"/></linearGradient></defs><path d="${path} V90 H10 Z" fill="url(#area)"/><path d="${path}" stroke="#348ff1" stroke-width="2" fill="none" stroke-linejoin="round"/><circle cx="${x(through)}" cy="${y(b)}" r="3" fill="#348ff1"/></svg>`;}
