document.addEventListener('click',e=>{const button=e.target.closest('[data-action]');if(button&&!button.disabled)runAction(button.dataset.action);});
document.addEventListener('input',e=>{const el=e.target,name=el.name;if(!name)return;if(name==='categorySearch'){categoryQuery=el.value;$('#category-results').innerHTML=categoryRows(state.categories.filter(c=>c.name.toLowerCase().includes(categoryQuery.toLowerCase())));return;}if(name==='simulation'){simValue=el.value;updateSimulation();return;}if(name==='moveSearch'){const pos=el.selectionStart;filter.query=el.value;movements();const input=$('[name="moveSearch"]');input.focus();input.setSelectionRange(pos,pos);return;}if(name==='advanceSearch'){const pos=el.selectionStart;advanceSearch=el.value;advances();const input=$('[name="advanceSearch"]');input.focus();input.setSelectionRange(pos,pos);return;}if(name==='rateCount'){rateChoice=el.value.trim()?Number(el.value):NaN;if($('#rate-total'))$('#rate-total').textContent=el.value?'Totale '+money((()=>{try{return cents(draft.amount||'0')}catch{return 0}})()*rateChoice):'Scegli un numero';document.querySelectorAll('.rate-option').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-checked','false');b.querySelector('.check-badge')?.remove();});return;}if(draft){draft[name]=el.type==='checkbox'?el.checked:el.value;if(name==='date'&&el.parentElement.querySelector('.date-value'))el.parentElement.querySelector('.date-value').textContent=el.value?dateLabel(el.value)+' '+el.value.slice(0,4):'Scegli data';if(name==='amount')el.style.width=Math.max(4,el.value.length)+'ch';}});
document.addEventListener('change',e=>{if(e.target.id==='backup-file'){const file=e.target.files[0];if(!file)return;if(file.size>2000000){toast('File troppo grande per la demo.');return;}const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);validateDemo(data);confirmDialog('Sostituire i dati della demo?',`${data.operations.length} movimenti e ${data.advances.length} anticipi. La demo attuale resterà esportabile come copia precedente.`,'Importa demo',()=>{previousBackup=structuredClone(state);state=data;closeModal();render();toast('Demo importata');});}catch{toast('File non valido: scegli un backup DEMO del prototipo. Nessun dato modificato.');}};reader.readAsText(file);}if(e.target.name==='frequency'&&draft)draft.frequency=e.target.value;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();overlay.innerHTML?closeModal():back();}if(e.key==='Tab'&&overlay.innerHTML){const nodes=[...overlay.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
function validateDemo(d){if(d.prototype!==1||!Number.isSafeInteger(d.opening)||Math.abs(d.opening)>999999999||!Number.isSafeInteger(d.reserve)||d.reserve<0||d.reserve>999999999)throw Error('Formato');for(const k of ['operations','advances','refunds','categories','series'])if(!Array.isArray(d[k])||d[k].length>5000)throw Error('Archivio');validDate(d.horizon);if(d.horizon<TODAY)throw Error('Periodo');if(!d.categories.length||d.categories.some(c=>!Number.isInteger(c.id)||typeof c.name!=='string'||c.name.length>40||!PATHS[c.icon]))throw Error('Categorie');for(const k of ['operations','advances','refunds','series']){if(new Set(d[k].map(x=>x.id)).size!==d[k].length)throw Error('ID');d[k].forEach(x=>{if(!Number.isSafeInteger(x.cents)||Math.abs(x.cents)>999999999)throw Error('Importi');validDate(x.date||x.start,k==='advances'||k==='refunds');});}d.operations.forEach(o=>{if(!['actual','planned'].includes(o.status)||!['income','expense','adjustment'].includes(o.kind)||!d.categories.some(c=>c.id===o.category))throw Error('Movimento');});d.advances.forEach(a=>{if(a.cents<=0||typeof a.description!=='string'||!a.debtor)throw Error('Anticipo');const rs=d.refunds.filter(r=>r.advance===a.id);if(rs.reduce((s,r)=>s+r.cents,0)>a.cents)throw Error('Residuo');});d.refunds.forEach(r=>{const a=d.advances.find(a=>a.id===r.advance);if(!a||r.cents<=0||r.date<a.date)throw Error('Rimborso');});}
// Interfaccia locale per catture e QA riproducibili, mai eseguita contro i dati Android.
window.Prototype={reset,go,runAction,getState:()=>structuredClone(state),totals,open:(p)=>runAction(p),setState:d=>{validateDemo(d);state=structuredClone(d);render();},setTheme:t=>{theme=t;render();},setLarge:b=>{textLarge=b;render();}};
render();
